    $Checkpoint | Add-Member NoteProperty FailureUtc $failureUtc -Force
    $Checkpoint.UpdatedUtc=$failureUtc
    try { Write-WsmJson $Path $Checkpoint } catch { $writeError=$_.Exception.Message;if($Checkpoint.PSObject.Properties['CheckpointWriteError']){$Checkpoint.CheckpointWriteError=$writeError}else{$Checkpoint | Add-Member NoteProperty CheckpointWriteError $writeError -Force};Write-Warning ('Unable to persist delta checkpoint failure detail: '+$writeError) }
}
function Assert-WsmDeltaVolumePaths([string]$Path,[string[]]$Others) {
