function Assert-WsmDeltaTransportMetadata($Transport) {
    $names=@('base/manifest.json','base/plan.json','base/artifacts.jsonl','current/manifest.json','current/plan.json','current/artifacts.jsonl','current/freeze.json','delta/summary.json','delta/changes.jsonl','delta/records.jsonl','delta/blobs.jsonl')
