function Get-WsmDeltaDirectoryMemberLimit { 100000 }
function Assert-WsmDeltaDirectoryMemberBudget([object[]]$Members) {
    $count=@($Members).Count;$limit=Get-WsmDeltaDirectoryMemberLimit
    if($count -gt $limit){throw ('Delta directory exceeds its bounded '+$limit+' member budget; reduce the approved transfer scope.')}
