function Import-WsmArtifactDeltaDirectory {
    [CmdletBinding()]param([Parameter(Mandatory)][string]$TransportPath,[Parameter(Mandatory)][string]$ExpectedHash,[Parameter(Mandatory)][string]$OutputDirectory,[Parameter(Mandatory)][string]$ScratchDirectory,$CancellationToken=$null)
