    try{foreach($name in $requiredNames){$src=Join-Path $source ($name.Replace('/','\'));$dest=Join-Path $root ($name.Replace('/','\'));[void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($dest));Copy-WsmDeltaFileCancellable $src $dest $CancellationToken 'DeltaDirectoryImportCopy'};$transportOut=Join-Path $root 'transport.json';Copy-WsmDeltaFileCancellable $TransportPath $transportOut $CancellationToken 'DeltaDirectoryIndexCopy';$valid=Test-WsmDeltaVolumeTransportContents $root $transport $ExpectedHash $CancellationToken;[pscustomobject]@{Directory=$root;TransportPath=$transportOut;TransportHash=$ExpectedHash;PairId=$transport.PairId;BaseManifestHash=$transport.BaseManifestHash;CurrentManifestHash=$transport.CurrentManifestHash;Generation=$valid.CurrentManifest.Generation;ChangedRecords=$valid.ChangedRecords;Valid=$true;Mode='Directory'}}catch{Remove-WsmDeltaImportRootIfOwned $root $output;throw}
}
function Export-WsmArtifactDeltaByProfile {
    [CmdletBinding()]param([Parameter(Mandatory)]$OutputProfile,[Parameter(Mandatory)][string]$OutputDirectory,[Parameter(Mandatory)][string]$ScratchDirectory,[Parameter(Mandatory)][hashtable]$DeltaArguments,$CancellationToken=$null)
    if($OutputProfile.Mode -cnotin @('Zip','Directory')){throw 'OutputProfile mode must be Zip or Directory.'}
    if($OutputProfile.Mode -ceq 'Zip'){$bytes=[long]0;if(-not [long]::TryParse([string]$OutputProfile.VolumeBytes,[ref]$bytes) -or $bytes -lt 128MB -or $bytes -gt 1GB -or ($bytes % 1MB) -ne 0){throw 'OutputProfile ZIP size must be a whole MiB from 128 through 1024.'};$invokeArgs=@{};foreach($key in $DeltaArguments.Keys){$invokeArgs[$key]=$DeltaArguments[$key]};$invokeArgs.OutputDirectory=$OutputDirectory;$invokeArgs.ScratchDirectory=$ScratchDirectory;$invokeArgs.VolumeBytes=$bytes;if($CancellationToken){$invokeArgs.CancellationToken=$CancellationToken};return Export-WsmArtifactDeltaVolumes @invokeArgs}
    if([long]$OutputProfile.VolumeBytes -ne 0){throw 'Directory OutputProfile must have VolumeBytes=0.'};$invokeArgs=@{};foreach($key in $DeltaArguments.Keys){$invokeArgs[$key]=$DeltaArguments[$key]};$invokeArgs.OutputDirectory=$OutputDirectory;$invokeArgs.ScratchDirectory=$ScratchDirectory;if($CancellationToken){$invokeArgs.CancellationToken=$CancellationToken};Export-WsmArtifactDeltaDirectory @invokeArgs
}
function Import-WsmArtifactDeltaByProfile {
    [CmdletBinding()]param([Parameter(Mandatory)]$OutputProfile,[Parameter(Mandatory)][string]$TransportPath,[Parameter(Mandatory)][string]$ExpectedHash,[Parameter(Mandatory)][string]$OutputDirectory,[Parameter(Mandatory)][string]$ScratchDirectory,$CancellationToken=$null)
    if($OutputProfile.Mode -cnotin @('Zip','Directory')){throw 'OutputProfile mode must be Zip or Directory.'};$transport=Read-WsmJson $TransportPath
